const cfg = $getWorkflowStaticData('global');
if (!cfg._initialized) {
  cfg.BYBIT_API_KEY = 'YOUR_BYBIT_API_KEY';
  cfg.BYBIT_API_SECRET = 'YOUR_BYBIT_API_SECRET';
  cfg.BYBIT_TESTNET = 'false';
  cfg.OPENROUTER_API_KEY = 'YOUR_OPENROUTER_API_KEY';
  cfg.OPENROUTER_MODEL = 'anthropic/claude-sonnet-4-20250514';
  cfg.TELEGRAM_CHAT_ID = '543663073';
  cfg.MAX_RISK_PER_TRADE = '1';
  cfg.MAX_DAILY_LOSS = '3';
  cfg.MAX_OPEN_POSITIONS = '3';
  cfg.MIN_RISK_REWARD = '3';
  cfg.MIN_CONFIDENCE = '75';
  cfg.MIN_VOLUME_24H = '50000000';
  cfg.WEBHOOK_URL = 'https://YOUR-N8N-URL/';
  cfg._initialized = true;
}
// Pass through telegram message
return $input.all();

// =============================================
// Parse Telegram command
// =============================================
const msg = $input.first().json;
const text = (msg.message?.text || '').trim();
const chatId = msg.message?.chat?.id?.toString() || '';
const cfg = $getWorkflowStaticData('global');
const allowedChat = cfg.TELEGRAM_CHAT_ID;

// Security: only allow commands from authorized chat
if (chatId !== allowedChat) {
  return [{ json: { command: '_unauthorized', chatId } }];
}

const parts = text.split(/\s+/);
const command = parts[0].toLowerCase();
const args = parts.slice(1);

return [{ json: { command, args, chatId, rawText: text } }];

// /status — current positions, P&L, balance
const cfg = $getWorkflowStaticData('global');
const crypto = require('crypto');

const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;

async function signedGet(endpoint, params) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const qs = Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&');
  const preSign = timestamp + apiKey + recvWindow + qs;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}${endpoint}?${qs}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    }
  });
}

// Get balance
const balResp = await signedGet.call(this, '/v5/account/wallet-balance', { accountType: 'UNIFIED' });
let equity = 0, availableBalance = 0;
try {
  equity = parseFloat(balResp.result.list[0].totalEquity);
  availableBalance = parseFloat(balResp.result.list[0].totalAvailableBalance);
} catch(e) {}

// Get positions
let positions = [];
try {
  const posResp = await signedGet.call(this, '/v5/position/list', {
    category: 'linear', settleCoin: 'USDT'
  });
  if (posResp.retCode === 0) {
    positions = (posResp.result?.list || []).filter(p => parseFloat(p.size) > 0);
  }
} catch(e) {}

// Get daily P&L
const today = new Date();
today.setHours(0, 0, 0, 0);
let dailyPnl = 0;
try {
  const pnlResp = await signedGet.call(this, '/v5/position/closed-pnl', {
    category: 'linear', startTime: today.getTime().toString(), limit: '100'
  });
  if (pnlResp.retCode === 0) {
    dailyPnl = (pnlResp.result?.list || []).reduce((s, p) => s + parseFloat(p.closedPnl), 0);
  }
} catch(e) {}

const store = $getWorkflowStaticData('global');
const botStopped = store.botStopped || false;
const tradingMode = store.tradingMode || 'both';
const riskOverride = store.riskOverride || null;
const env = isTestnet ? '🧪 TESTNET' : '🔴 MAINNET';
const botStatus = botStopped ? '⛔ ОСТАНОВЛЕН' : '🟢 АКТИВЕН';

let msg = `📊 <b>Status Report</b> ${env}\n\n`;
msg += `<b>Статус бота:</b> ${botStatus}\n`;
msg += `<b>Режим:</b> ${tradingMode}\n`;
msg += `<b>Риск на сделку:</b> ${riskOverride || cfg.MAX_RISK_PER_TRADE || '1'}%\n\n`;
msg += `<b>Эквити:</b> <code>$${equity.toFixed(2)}</code>\n`;
msg += `<b>Доступно:</b> <code>$${availableBalance.toFixed(2)}</code>\n`;
msg += `<b>P&L за день:</b> <code>$${dailyPnl.toFixed(2)}</code>\n\n`;

if (positions.length > 0) {
  msg += `<b>Открытые позиции (${positions.length}):</b>\n`;
  for (const p of positions) {
    const pnl = parseFloat(p.unrealisedPnl);
    const emoji = pnl >= 0 ? '🟢' : '🔴';
    msg += `${emoji} <b>${p.symbol}</b> ${p.side}\n`;
    msg += `   Вход: <code>${p.avgPrice}</code> | Цена: <code>${p.markPrice}</code>\n`;
    msg += `   P&L: <code>$${pnl.toFixed(2)}</code> | SL: <code>${p.stopLoss || 'N/A'}</code>\n\n`;
  }
} else {
  msg += '<i>Нет открытых позиций</i>\n';
}

msg += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message: msg } }];

// /stop — emergency stop all workflows
const cfg = $getWorkflowStaticData('global');
const crypto = require('crypto');

const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;

// Cancel all orders
async function signedPost(endpoint, body) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const bodyStr = JSON.stringify(body);
  const preSign = timestamp + apiKey + recvWindow + bodyStr;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}${endpoint}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    },
    body
  });
}

try {
  await signedPost.call(this, '/v5/order/cancel-all', { category: 'linear', settleCoin: 'USDT' });
  await signedPost.call(this, '/v5/order/cancel-all', { category: 'spot' });
} catch(e) {}

// Set global stop flag
const store = $getWorkflowStaticData('global');
store.botStopped = true;
store.stoppedAt = Date.now();

let msg = '⛔ <b>ЭКСТРЕННАЯ ОСТАНОВКА</b>\n\n';
msg += 'Все ордера отменены.\n';
msg += 'Бот остановлен.\n';
msg += 'Для возобновления отправь /start\n';
msg += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message: msg } }];

// /start — resume bot operations
const store = $getWorkflowStaticData('global');
const wasStopped = store.botStopped || false;

store.botStopped = false;
store.stoppedAt = null;

let msg = '';
if (wasStopped) {
  msg = '🟢 <b>Бот возобновлён</b>\n\n';
  msg += 'Торговля снова активна.\n';
  msg += 'Market Scanner продолжит сканирование при следующем запуске по расписанию.\n';
} else {
  msg = '🟢 <b>Бот уже работает</b>\n\n';
  msg += 'Бот не был остановлен.\n';
}

const tradingMode = store.tradingMode || 'both';
const riskOverride = store.riskOverride || cfg.MAX_RISK_PER_TRADE || '1';
msg += `\n<b>Режим:</b> ${tradingMode}\n`;
msg += `<b>Риск:</b> ${riskOverride}%\n`;
msg += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message: msg } }];

// /report — daily/weekly report
const cfg = $getWorkflowStaticData('global');
const crypto = require('crypto');
const args = $input.first().json.args || [];
const period = args[0] || 'day'; // day or week

const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;

async function signedGet(endpoint, params) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const qs = Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&');
  const preSign = timestamp + apiKey + recvWindow + qs;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}${endpoint}?${qs}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    }
  });
}

const now = new Date();
const start = new Date(now);
if (period === 'week') {
  start.setDate(start.getDate() - 7);
} else {
  start.setHours(0, 0, 0, 0);
}

let trades = [];
try {
  const pnlResp = await signedGet.call(this, '/v5/position/closed-pnl', {
    category: 'linear', startTime: start.getTime().toString(), limit: '100'
  });
  if (pnlResp.retCode === 0) {
    trades = pnlResp.result?.list || [];
  }
} catch(e) {}

const totalPnl = trades.reduce((s, t) => s + parseFloat(t.closedPnl), 0);
const wins = trades.filter(t => parseFloat(t.closedPnl) > 0).length;
const losses = trades.filter(t => parseFloat(t.closedPnl) < 0).length;
const winRate = trades.length > 0 ? (wins / trades.length * 100).toFixed(1) : '0';

const periodLabel = period === 'week' ? 'Неделя' : 'День';
const emoji = totalPnl >= 0 ? '📈' : '📉';

let msg = `${emoji} <b>Отчёт за ${periodLabel.toLowerCase()}</b>\n\n`;
msg += `<b>Сделок:</b> ${trades.length}\n`;
msg += `<b>Прибыльных:</b> ${wins} | <b>Убыточных:</b> ${losses}\n`;
msg += `<b>Win Rate:</b> ${winRate}%\n`;
msg += `<b>Итого P&L:</b> <code>$${totalPnl.toFixed(2)}</code>\n\n`;

if (trades.length > 0) {
  msg += '<b>Последние сделки:</b>\n';
  for (const t of trades.slice(0, 10)) {
    const pnl = parseFloat(t.closedPnl);
    const e = pnl >= 0 ? '✅' : '❌';
    msg += `${e} ${t.symbol} — $${pnl.toFixed(2)}\n`;
  }
}

msg += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message: msg } }];

// /pairs — show current trading pairs by volume
const cfg = $getWorkflowStaticData('global');
const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const MIN_VOLUME = parseFloat(cfg.MIN_VOLUME_24H || '50000000');

let pairs = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}/v5/market/tickers?category=spot`
  });
  if (resp.retCode === 0) {
    pairs = resp.result.list
      .filter(t => t.symbol.endsWith('USDT'))
      .map(t => ({
        symbol: t.symbol,
        price: parseFloat(t.lastPrice),
        volume24h: parseFloat(t.turnover24h),
        change: parseFloat(t.price24hPcnt) * 100
      }))
      .filter(t => t.volume24h >= MIN_VOLUME)
      .sort((a, b) => b.volume24h - a.volume24h)
      .slice(0, 20);
  }
} catch(e) {}

let msg = `📋 <b>Торговые пары</b> (мин. объём $${(MIN_VOLUME/1e6).toFixed(0)}M)\n\n`;
msg += `<b>Найдено:</b> ${pairs.length} пар\n\n`;

for (let i = 0; i < pairs.length; i++) {
  const p = pairs[i];
  const changeEmoji = p.change >= 0 ? '🟢' : '🔴';
  msg += `<b>${i+1}.</b> ${p.symbol}\n`;
  msg += `   Цена: <code>${p.price}</code> ${changeEmoji} ${p.change.toFixed(2)}%\n`;
  msg += `   Объём: <code>$${(p.volume24h/1e6).toFixed(1)}M</code>\n\n`;
}

msg += `⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message: msg } }];

// /set_risk <value> — change risk per trade percentage
const args = $input.first().json.args || [];
const store = $getWorkflowStaticData('global');

let msg = '';

if (args.length === 0 || isNaN(parseFloat(args[0]))) {
  const currentRisk = store.riskOverride || cfg.MAX_RISK_PER_TRADE || '1';
  msg = `⚙️ <b>Настройка риска</b>\n\n`;
  msg += `<b>Текущий риск:</b> ${currentRisk}% на сделку\n\n`;
  msg += `Использование: <code>/set_risk 0.5</code>\n`;
  msg += `Допустимые значения: 0.1 — 3\n`;
} else {
  const newRisk = parseFloat(args[0]);

  if (newRisk < 0.1 || newRisk > 3) {
    msg = '❌ <b>Ошибка</b>\n\nРиск должен быть от 0.1% до 3%\n';
  } else {
    store.riskOverride = newRisk.toString();
    msg = `✅ <b>Риск обновлён</b>\n\n`;
    msg += `<b>Новый риск:</b> ${newRisk}% на сделку\n`;
    msg += `<b>Макс. потери в день:</b> ${cfg.MAX_DAILY_LOSS || '3'}%\n`;
  }
}

msg += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;
return [{ json: { message: msg } }];

// /mode <spot|futures|both> — switch trading mode
const args = $input.first().json.args || [];
const store = $getWorkflowStaticData('global');

let msg = '';
const validModes = ['spot', 'futures', 'both'];

if (args.length === 0 || !validModes.includes(args[0].toLowerCase())) {
  const currentMode = store.tradingMode || 'both';
  msg = `⚙️ <b>Режим торговли</b>\n\n`;
  msg += `<b>Текущий:</b> ${currentMode}\n\n`;
  msg += `Использование: <code>/mode spot|futures|both</code>\n`;
  msg += `• <b>spot</b> — только спот\n`;
  msg += `• <b>futures</b> — только фьючерсы\n`;
  msg += `• <b>both</b> — спот + фьючерсы\n`;
} else {
  const newMode = args[0].toLowerCase();
  store.tradingMode = newMode;

  const modeNames = { spot: 'Только спот', futures: 'Только фьючерсы', both: 'Спот + фьючерсы' };
  msg = `✅ <b>Режим изменён</b>\n\n`;
  msg += `<b>Новый режим:</b> ${modeNames[newMode]}\n`;
}

msg += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;
return [{ json: { message: msg } }];

// /help — show available commands
let msg = '🤖 <b>Gerchik Bot</b>

';
msg += '<b>💰 БАЛАНС И ПОЗИЦИИ:</b>
';
msg += '/balance — баланс
';
msg += '/status — позиции
';
msg += '/pairs — топ пары

';
msg += '<b>⚙️ УПРАВЛЕНИЕ:</b>
';
msg += '/stop — стоп
';
msg += '/start — старт
';
msg += '/model — список AI моделей
';
msg += '/model 3 — сменить модель
';
msg += '/set_risk 0.5 — изменить % риска
';
msg += '/mode spot|futures|both — режим

';
msg += '<b>📊 АНАЛИТИКА (WF7):</b>
';
msg += '/report — P&L за день
';
msg += '/report week — P&L за неделю
';
msg += '/stats — общая статистика
';
msg += '/rejected — отклонённые сигналы
';
msg += '/accepted — принятые сигналы
';
msg += '/explain ETHUSDT — разбор пары

';
msg += '<b>🏥 МЕДИК (WF8):</b>
';
msg += '/health — здоровье бота и API
';
msg += '/errors — последние ошибки

';
msg += '/help — справка
';

return [{ json: { message: msg } }];

// /model [name|number] — view or switch AI model
const args = $input.first().json.args || [];
const store = $getWorkflowStaticData('global');

const models = [
  { num: 1, id: 'anthropic/claude-sonnet-4-20250514', name: 'Claude Sonnet 4', desc: 'Anthropic — быстрый и умный' },
  { num: 2, id: 'anthropic/claude-opus-4-20250514', name: 'Claude Opus 4', desc: 'Anthropic — самый мощный' },
  { num: 3, id: 'deepseek/deepseek-chat-v3-0324', name: 'DeepSeek V3', desc: 'DeepSeek — быстрый, дешёвый' },
  { num: 4, id: 'deepseek/deepseek-reasoner', name: 'DeepSeek R1', desc: 'DeepSeek — с рассуждением' },
  { num: 5, id: 'openai/gpt-4o', name: 'GPT-4o', desc: 'OpenAI — мультимодальный' },
  { num: 6, id: 'openai/o3-mini', name: 'o3-mini', desc: 'OpenAI — быстрый reasoning' },
  { num: 7, id: 'google/gemini-2.5-pro-preview-03-25', name: 'Gemini 2.5 Pro', desc: 'Google — мощный, большой контекст' },
  { num: 8, id: 'google/gemini-2.5-flash-preview', name: 'Gemini 2.5 Flash', desc: 'Google — быстрый и дешёвый' },
  { num: 9, id: 'meta-llama/llama-4-maverick', name: 'Llama 4 Maverick', desc: 'Meta — открытая модель' },
  { num: 10, id: 'qwen/qwen-2.5-72b-instruct', name: 'Qwen 2.5 72B', desc: 'Alibaba — мощная открытая' }
];

const currentModel = store.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-20250514';
let msg = '';

if (args.length === 0) {
  // Show current model and list
  const current = models.find(m => m.id === currentModel);
  const currentName = current ? current.name : currentModel;
  msg = `🤖 <b>AI Модель</b>\n\n`;
  msg += `<b>Текущая:</b> ${currentName}\n`;
  msg += `<code>${currentModel}</code>\n\n`;
  msg += `<b>Доступные модели:</b>\n\n`;
  for (const m of models) {
    const active = m.id === currentModel ? ' ✅' : '';
    msg += `<b>${m.num}.</b> ${m.name}${active}\n`;
    msg += `   <i>${m.desc}</i>\n`;
    msg += `   <code>${m.id}</code>\n\n`;
  }
  msg += `<b>Использование:</b>\n`;
  msg += `<code>/model 3</code> — выбрать по номеру\n`;
  msg += `<code>/model deepseek/deepseek-chat-v3-0324</code> — указать ID\n`;
} else {
  const input = args[0];
  const num = parseInt(input);
  let selected = null;

  if (!isNaN(num) && num >= 1 && num <= models.length) {
    selected = models[num - 1];
  } else {
    // Try to match by id or partial name
    selected = models.find(m => m.id === input || m.id.includes(input));
  }

  if (selected) {
    store.OPENROUTER_MODEL = selected.id;
    msg = `✅ <b>Модель изменена</b>\n\n`;
    msg += `<b>Новая модель:</b> ${selected.name}\n`;
    msg += `<code>${selected.id}</code>\n`;
    msg += `<i>${selected.desc}</i>\n`;
  } else {
    // Custom model ID — set directly
    store.OPENROUTER_MODEL = input;
    msg = `✅ <b>Модель изменена</b>\n\n`;
    msg += `<b>Новая модель:</b> <code>${input}</code>\n`;
    msg += `<i>Кастомная модель — убедитесь что она доступна на OpenRouter</i>\n`;
  }
}

msg += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;
return [{ json: { message: msg } }];

// /balance — detailed wallet balance breakdown
const cfg = $getWorkflowStaticData('global');
const crypto = require('crypto');

const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;

async function signedGet(endpoint, params) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const qs = Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&');
  const preSign = timestamp + apiKey + recvWindow + qs;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}${endpoint}?${qs}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    }
  });
}

const env = isTestnet ? '🧪 TESTNET' : '💰 MAINNET';
let msg = `${env} <b>Баланс кошелька</b>\n\n`;

try {
  const resp = await signedGet.call(this, '/v5/account/wallet-balance', { accountType: 'UNIFIED' });
  if (resp.retCode === 0 && resp.result?.list?.length > 0) {
    const wallet = resp.result.list[0];
    const equity = parseFloat(wallet.totalEquity || 0);
    const available = parseFloat(wallet.totalAvailableBalance || 0);
    const walletBal = parseFloat(wallet.totalWalletBalance || 0);
    const unrealised = parseFloat(wallet.totalPerpUPL || 0);
    const margin = parseFloat(wallet.totalInitialMargin || 0);

    msg += `<b>Общий эквити:</b> <code>$${equity.toFixed(2)}</code>\n`;
    msg += `<b>Баланс кошелька:</b> <code>$${walletBal.toFixed(2)}</code>\n`;
    msg += `<b>Доступно:</b> <code>$${available.toFixed(2)}</code>\n`;
    if (unrealised !== 0) msg += `<b>Нереализ. P&L:</b> <code>$${unrealised.toFixed(2)}</code>\n`;
    if (margin > 0) msg += `<b>Маржа:</b> <code>$${margin.toFixed(2)}</code>\n`;

