// Get trades for today and week
const now = new Date();
const todayStart = new Date(now); todayStart.setHours(0,0,0,0);
const weekStart = new Date(now); weekStart.setDate(weekStart.getDate() - 7);

let todayTrades = [], weekTrades = [];
try {
  const resp = await signedGet.call(this, '/v5/position/closed-pnl', { category: 'linear', startTime: weekStart.getTime().toString(), limit: '100' });
