function calcStats(trades) {
  const wins = trades.filter(t => parseFloat(t.closedPnl) > 0);
  const losses = trades.filter(t => parseFloat(t.closedPnl) < 0);
  const totalPnl = trades.reduce((s,t) => s + parseFloat(t.closedPnl), 0);
  const winRate = trades.length > 0 ? (wins.length / trades.length * 100).toFixed(1) : '0';
  return { total: trades.length, wins: wins.length, losses: losses.length, pnl: totalPnl, winRate };
}

