  msg += '<i>Нет ошибок за последние 24 часа</i> ✅\n';
} else {
  // Group by workflow and error type
  const grouped = {};
  for (const err of allErrors) {
    const key = `${err.workflow}|${err.code || 'unknown'}`;
    if (!grouped[key]) grouped[key] = { ...err, count: 0 };
    grouped[key].count++;
  }

  let i = 1;
  for (const [, g] of Object.entries(grouped).slice(0, 10)) {
    const time = new Date(g.time).toLocaleTimeString('ru-RU', { timeZone: 'Europe/Moscow', hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const level = g.code === '401' || g.code === '500' ? '🔴' : '🟡';
